from rules import amount


def solve(data):
    cutoff = data.get('cutoff', 10**9)
    winners = {}

    for position, event in enumerate(data.get('events', [])):
        if event.get('sequence', 0) > cutoff:
            continue

        if 'id' in event:
            identity = ('id', event['id'])
        else:
            identity = ('anonymous', position)

        revision = event.get('revision', 0)
        previous = winners.get(identity)
        if previous is None or revision >= previous[0]:
            winners[identity] = (revision, event)

    balances = dict(data.get('opening', {}))
    mode = data.get('rounding', 'half_up')

    for _, event in winners.values():
        if event.get('void', False) is True:
            continue
        key = f"{event.get('account', 'default')}|{event.get('currency', 'USD')}"
        balances.setdefault(key, 0)
        balances[key] += amount(event, mode)

    return {'balances': balances}
